<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarLecturaProduccion, listarLecturasProduccion, type LecturaProduccion } from '../services/lecturas'
const records=ref<LecturaProduccion[]>([]),meters=ref<{id:number;nombre:string}[]>([]),selected=ref<LecturaProduccion|null>(null),loading=ref(false),error=ref(''),success=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),summary=reactive({registros:0,fisicas:0,virtuales:0,volumen_total:0}),filters=reactive({criterio:'',desde:'',hasta:'',tipo:'',componente_id:''})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarLecturasProduccion(filters,target);records.value=r.data;meters.value=r.macromedidores;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(summary,r.resumen)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function remove(item:LecturaProduccion){if(!confirm(`¿Eliminar la lectura #${item.id} de ${item.macromedidor}? Esta acción no se puede revertir.`))return;try{await eliminarLecturaProduccion(item.id);selected.value=null;success.value='Lectura eliminada correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
function clear(){Object.assign(filters,{criterio:'',desde:'',hasta:'',tipo:'',componente_id:''});load(1)}const fmt=(value:number)=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:3}).format(value);const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Producción / Lecturas</nav><header class="hero"><div class="mark">LE</div><div><small>DANA · PRODUCCIÓN</small><h1>Lecturas de producción</h1><p>Consulta el historial consolidado de macromedidores físicos y virtuales.</p></div><RouterLink to="/modulos/operaciones/produccion/macromedidores">Tomar nueva lectura →</RouterLink></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>LECTURAS ENCONTRADAS</small><b>{{summary.registros}}</b></article><article><small>LECTURAS FÍSICAS</small><b>{{summary.fisicas}}</b></article><article><small>LECTURAS VIRTUALES</small><b>{{summary.virtuales}}</b></article><article><small>VOLUMEN ACUMULADO</small><b>{{fmt(summary.volumen_total)}} m³</b></article></section><form class="filters" @submit.prevent="load(1)"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Macromedidor, sistema o usuario"></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><label>Tipo<select v-model="filters.tipo"><option value="">Todos</option><option value="fisico">Físico</option><option value="virtual">Virtual</option></select></label><label>Macromedidor<select v-model="filters.componente_id"><option value="">Todos</option><option v-for="item in meters" :key="item.id" :value="String(item.id)">{{item.nombre}}</option></select></label><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="panel"><div v-if="loading" class="empty">Cargando lecturas…</div><div v-else-if="!records.length" class="empty">No se encontraron lecturas registradas.</div><div v-else class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Macromedidor</th><th>Tipo</th><th>Distrito / sistema</th><th>Lectura</th><th>Usuario</th><th></th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td><b>{{item.fecha}}</b><span>{{item.hora}}</span></td><td><b>{{item.macromedidor}}</b><span>#{{item.componente_id}}</span></td><td><i :class="item.tipo">{{item.tipo==='fisico'?'Físico':'Virtual'}}</i></td><td><b>{{item.distrito}}</b><span>{{item.sistema}}</span></td><td><strong>{{fmt(item.lectura)}}</strong> {{item.unidad}}</td><td>{{item.usuario}}</td><td><button @click="selected=item">Ver detalle</button></td></tr></tbody></table></div><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}} · {{total}} lecturas</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="dialog"><header><div><small>LECTURA #{{selected.id}}</small><h2>{{selected.macromedidor}}</h2></div><button @click="selected=null">×</button></header><div v-if="selected.imagen_url" class="photo"><img :src="selected.imagen_url" alt="Evidencia de lectura"><a :href="selected.imagen_url" target="_blank">Abrir imagen original</a></div><div v-else class="no-photo">Lectura virtual o registro sin evidencia fotográfica.</div><dl><div><dt>Tipo</dt><dd>{{selected.tipo==='fisico'?'Macromedidor físico':'Macromedidor virtual'}}</dd></div><div><dt>Fecha y hora</dt><dd>{{selected.fecha_hora}}</dd></div><div><dt>Distrito</dt><dd>{{selected.distrito}}</dd></div><div><dt>Sistema</dt><dd>{{selected.sistema}}</dd></div><div v-if="selected.valor_ingresado!==null"><dt>Caudal ingresado</dt><dd>{{fmt(selected.valor_ingresado)}} L/s</dd></div><div><dt>Lectura almacenada</dt><dd><strong>{{fmt(selected.lectura)}} {{selected.unidad}}</strong></dd></div><div><dt>Registrado por</dt><dd>{{selected.usuario}}</dd></div></dl><footer><button class="delete" @click="remove(selected)">Eliminar lectura</button><button @click="selected=null">Cerrar</button></footer></section></div></div></template>
